ReUrlsFromReq := func(req, dnslog_domain) {
    reqStr := codec.DecodeUrl(string(req))~

    urlPatterns := []string{`[a-zA-z]+://[^\s]*`, `[A-Za-z]+://((25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)(\.)){3}(25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)
`}
    modifiedReq := reqStr
    for _, pattern := range urlPatterns {
        matches := re.FindAll(reqStr, pattern)
        for _, match := range matches {
            modifiedReq = str.ReplaceAll(modifiedReq, string(match), dnslog_domain)
        }
    }


    return modifiedReq
}

