// 检查DNS Log
    events, err := risk.CheckDNSLogByToken(token, 10)
    if err {
        yakit.Error("检查DNS Log失败: %v", err)
    } else if len(events) > 0 {
        // 可以在这里添加更多的漏洞利用代码
                    // 创建风险记录
            risk.NewRisk(url, 
