                risk.request(req1),
                risk.response(rsp1),
                risk.level("high"),
                risk.payload(sprintf("替换URL为: %s", domain)),
                risk.description(sprintf(
                    "【确认漏洞】通过DNS回连技术确认存在服务端请求伪造(SSRF/url跳转)漏洞\n\n" +
                    "攻击详情：\n" +
                    "• 目标URL: %s\n" +
                    "• DNS回连域名: %s\n" +
                    "• 成功回连次数: %d\n\n" +
                    "风险评估：此漏洞允许攻击者让服务器发起对任意URL的请求，可能导致内网探测、敏感信息泄露等风险。",
                    url, domain, len(events))),
                risk.solution("【修复建议】\n1. 对URL参数进行严格验证\n2. 使用白名单机制限制可访问的域名\n3. 禁止访问内网地址\n4. 对HTTP请求进行适当的超时和大小限制"),
            )
    } else {
        println("未检测到DNS Log回调")
    }
